from ShazamKit import Shazam, models

class ShazamWrapper:
    def __init__(self, api_key):
        self.shazam = Shazam(api_key)

    def recognize_song(self, audio_file):
        with open(audio_file, 'rb') as file:
            data = file.read()
        recognize_result = self.shazam.recognize_song(data)
        return recognize_result

    def get_track_info(self, track_id):
        track_info = self.shazam.get_track_info(track_id)
        return track_info

    def get_artist_info(self, artist_id):
        artist_info = self.shazam.get_artist_info(artist_id)
        return artist_info

    def get_playlist_info(self, playlist_id):
        playlist_info = self.shazam.get_playlist_info(playlist_id)
        return playlist_info

    def get_lyrics(self, track_id):
        lyrics = self.shazam.get_lyrics(track_id)
        return lyrics

    def search_tracks(self, query):
        search_result = self.shazam.search_tracks(query)
        return search_result

    def get_top_charts(self):
        top_charts = self.shazam.get_top_charts()
        return top_charts

