import collectd
import requests
import json

SUMO_LOGIC_URL = 'https://api.sumologic.com/receiver/v1/http'

def configure_callback(conf):
    for node in conf.children:
        key = node.key.decode('utf-8')
        val = node.values[0].decode('utf-8')
        if key == 'SumoLogicUrl':
            global SUMO_LOGIC_URL
            SUMO_LOGIC_URL = val
        else:
            collectd.warning('Unknown config key: %s.' % key)

def write_callback(vl):
    data = {
        'timestamp': vl.time,
        'host': vl.host,
        'plugin': vl.plugin,
        'plugin_instance': vl.plugin_instance,
        'type': vl.type,
        'type_instance': vl.type_instance,
        'values': [vl.values[i] for i in range(len(vl.values))],
    }
    headers = {'Content-Type': 'application/json'}
    response = requests.post(SUMO_LOGIC_URL, data=json.dumps(data), headers=headers)
    if response.status_code != 200:
        collectd.error('Failed to send data to Sumo Logic: %s' % response.text)

collectd.register_config(configure_callback)
collectd.register_write(write_callback)

import collectd
import requests

# Sumo Logic HTTP source URL
sumo_url = 'https://<sumo_endpoint>/receiver/v1/http/telemetry'

def configure_callback(conf):
    """Receive configuration block"""
    for node in conf.children:
        key = node.key.lower()
        val = node.values[0]
        if key == 'sumo_url':
            global sumo_url
            sumo_url = val
        else:
            collectd.warning('unknown config key: %s' % key)

def dispatch_value(type_instance, type, plugin, value, time):
    """Send data to Sumo Logic"""
    data = {
        'metric': {
            'timestamp': int(time),
            'value': float(value),
            'type': str(type),
            'plugin': str(plugin),
            'type_instance': str(type_instance)
        },
        'source': 'collectd'
    }

    headers = {'Content-Type': 'application/json'}
    try:
        response = requests.post(sumo_url, json=data, headers=headers)
        if response.status_code != 200:
            collectd.error('Failed to send data to Sumo Logic: {}'.format(response.text))
    except requests.exceptions.RequestException as e:
        collectd.error('Failed to send data to Sumo Logic: {}'.format(e))

collectd.register_config(configure_callback)
collectd.register_write(dispatch_value)

