import os
import libheif
from PIL import Image

class HEIF:
    def __init__(self, filename):
        self.filename = filename
        self.heif_file = libheif.open_heif(filename)

    def save_as_png(self, output_filename):
        image = self.heif_file.get_thumbnail(1)
        img = Image.frombytes('RGB', (image.width, image.height), image.data, 'raw', 'RGB', (0, 1))
        img.save(output_filename, 'PNG')

    def save_as_jpeg(self, output_filename):
        image = self.heif_file.get_thumbnail(1)
        img = Image.frombytes('RGB', (image.width, image.height), image.data, 'raw', 'RGB', (0, 1))
        img.save(output_filename, 'JPEG')

    def get_metadata(self):
        return self.heif_file.get_metadata()

    def get_images(self):
        return [image for image in self.heif_file.get_images()]

