import re

def parse_cron_expressions(log_events):
    cron_expressions = []
    for event in log_events:
        message = event['message']
        # AWS CloudWatch Logs Insight query output usually contains the cron expression and the last executed timestamp
        # The cron expression is a string of 6 space-separated values, the last executed timestamp is the 7th value
        match = re.search(r'(\S+) (\S+) (\S+) (\S+) (\S+) (\S+) (\S+)', message)
        if match:
            cron_expressions.append({
                'cron_expression': ' '.join(match.groups()[:6]),
                'last_executed': match.groups()[6]
            })
    return cron_expressions

def format_cron_expressions(cron_expressions):
    formatted = []
    for cron in cron_expressions:
        formatted.append(f'Cron Expression: {cron["cron_expression"]}, Last Executed: {cron["last_executed"]}')
    return formatted

